class METARBulkUpdateController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Creates new instance of <c>METAPBulkUpdateController</c>
/// </summary>
protected void new()
{
    super();
 
    this.parmClassName(classStr(METARBulkUpdateService));
    this.parmMethodName(methodStr(METARBulkUpdateService, processOperation));
 
    this.parmDialogCaption("@MET:METARBulkUpdate");
}

/// <summary>
/// Sets the caption of the job
/// </summary>
/// <returns>Caption of the job</returns>
public ClassDescription caption()
{
    return "@MET:METARBulkUpdate";
}

/// <summary>
/// Method which is run while calling the corresponding menu item
/// </summary>
/// <param name = "args">Arguments passed from the menu item</param>
public static void main(Args args)
{
    METARBulkUpdateController controller;
 
    controller = new METARBulkUpdateController();
    controller.startOperation();
}
